require_once 'functions.php';require_admin();$id=(int)($_GET['id']??0);$row=['full_name'=>'','username'=>'','phone'=>''];$error='';
if($id){$st=$pdo->prepare("SELECT * FROM users WHERE id=? AND role='member'");$st->execute([$id]);$row=$st->fetch();if(!$row)exit('Member tidak ditemukan.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$phone=trim($_POST['phone']??'')?:null;$password=$_POST['password']??'';
 if($name===''||$username==='')$error='Nama dan username wajib diisi.';
 elseif(!$id&&strlen($password)<8)$error='Password awal minimal 8 karakter.';
 else {try{if($id){$sql="UPDATE users SET full_name=?,username=?,phone=?";$params=[$name,$username,$phone];if($password!==''){if(strlen($password)<8)throw new Exception('Password minimal 8 karakter.');$sql.=",password_hash=?";$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=" WHERE id=? AND role='member'";$params[]=$id;$pdo->prepare($sql)->execute($params);}else{$pdo->prepare("INSERT INTO users(full_name,username,phone,password_hash,role) VALUES(?,?,?,?, 'member')")->execute([$name,$username,$phone,password_hash($password,PASSWORD_DEFAULT)]);}flash('Data member berhasil disimpan.');header('Location: members.php');exit;}catch(PDOException $ex){$error='Username sudah digunakan. Gunakan username lain.';}catch(Exception $ex){$error=$ex->getMessage();}}
}
$pageTitle=$id?'Edit Member':'Tambah Member';$active='members';require 'header.php';
?>
